// Register once from your page
if ('serviceWorker' in navigator) {
  navigator.serviceWorker.register('/sw.js');
}

// sw.js — stale-while-revalidate for images
self.addEventListener('fetch', (event) => {
  if (event.request.destination === 'image') {
    event.respondWith(
      caches.open('img-v1').then(async (cache) => {
        const cached = await cache.match(event.request);
        const network = fetch(event.request).then((res) => {
          cache.put(event.request, res.clone());
          return res;
        });
        return cached ?? network; // instant paint, refresh behind the scenes
      }),
    );
  }
});

/* ❌ layout + paint every frame (janky) */
.drawer { transition: width 0.3s, left 0.3s; }

/* ✅ compositor-only (smooth) */
.drawer {
  transition: transform 0.3s, opacity 0.3s;
  will-change: transform;
}
.drawer[hidden] { transform: translateX(-100%); opacity: 0; }

